"""Snapshot-aware retrieval: related code is a lead, not proof of user ability."""
from __future__ import annotations
from dataclasses import asdict
from hashlib import sha256
import json,math,re
from time import perf_counter
from typing import Literal
from fastapi import Depends,Query
from pydantic import Field
from job_agent.schemas import StrictModel
from job_agent.knowledge.bm25_index import BM25Index
from job_agent.knowledge.contracts import KnowledgeChunk,RetrievedChunk
from job_agent.knowledge.vector_index import InMemoryVectorIndex
from job_agent.knowledge.rrf import reciprocal_rank_fusion
from job_agent.knowledge.index_manifest import declared_identity, manifest_for, valid_vector
from job_agent.knowledge.retrieval_policy import RetrievalSettings,output_budget
from job_agent.knowledge.reranker import apply_rerank
from job_agent.knowledge.markdown_chunks import markdown_ranges
from job_agent.resume_workspace.code_parser import parse_file,resolve_edges,is_test_path,PARSER_VERSION
from job_agent.resume_workspace.long_term import LongTermRepository,encoded,digest
from job_agent.resume_workspace.evidence_reference import EvidenceReference
from job_agent.resume_workspace.repository import WorkspaceConflict,WorkspaceNotFound

INDEX_VERSION=PARSER_VERSION+'/chunks-3-markdown-1'


def public_report(report):
    return {k:v for k,v in report.items() if k not in ('symbol_payload_hashes','chunk_payload_hashes','edges_hash','vector_manifest')}



class CodeQuery(StrictModel):
    snapshot_id: str=Field(min_length=1,max_length=100)
    query: str=Field(min_length=1,max_length=600)
    method: Literal['code_aware','symbol','keyword','flat','readme','dense','hybrid']='code_aware'
    limit: int=Field(default=5,ge=1,le=20)
    expand_relations: bool=True
    rerank: bool|None=None


class IndexRequest(StrictModel):
    snapshot_id: str=Field(min_length=1,max_length=100)


def _chunks(snapshot,path,text,parsed):
    """Both flat baseline and symbol blocks share exactly the same source text."""
    lines=text.splitlines(keepends=True);prefix=[0]
    for line in lines:prefix.append(prefix[-1]+len(line))
    result={};h=sha256(text.encode()).hexdigest()
    ranges=[(1,len(lines),None,'flat')]
    functions=[s for s in parsed.symbols if s.kind not in ('module','class')]
    if path.casefold().endswith(('.md','.markdown')):
        ranges += [(start,end,None,'markdown') for start,end in markdown_ranges(text)]
    else:
        ranges += [(s.start_line,s.end_line,s.symbol_id,'ast') for s in parsed.symbols if s.kind!='module']
        if not functions:ranges.append((1,len(lines),None,'ast'))
    for start,end,symbol,kind in ranges:
        cursor=start
        while cursor<=end:
            stop=cursor;size=0
            while stop<=end and stop-cursor<80 and size+len(lines[stop-1])<=12000:
                size+=len(lines[stop-1]);stop+=1
            if stop==cursor:cursor+=1;continue # Minified/oversized line: explicit omission, not a forged partial quote.
            quote=''.join(lines[cursor-1:stop-1]);identity=f'{snapshot}:{path}:{cursor}:{stop-1}:{kind}'
            if quote.strip():
                chunk=KnowledgeChunk(chunk_id='chunk-'+sha256(identity.encode()).hexdigest()[:28],
                    document_id=snapshot+':'+path,document_version=1,document_content_hash=h,text=quote,
                    chunk_index=len(result),start_offset=prefix[cursor-1],end_offset=prefix[stop-1],
                    metadata={'path':path,'start_line':cursor,'end_line':stop-1,'symbol_id':symbol,'granularity':kind,
                              'parser_status':parsed.status,'snapshot_id':snapshot,
                              'structural_fragment':kind=='markdown' and (cursor!=start or stop-1!=end)})
                result[chunk.chunk_id]=chunk
            cursor=stop
    return list(result.values())


class CodeRAGService:
    def __init__(self,workspace,*,embedding_backend=None,embedding_identity='local-configured-embedding',
                 reranker=None,retrieval_settings=None,projects=None,indexes=None):
        self.workspace=workspace;self.projects=projects or LongTermRepository(workspace)
        self.embedding_backend=embedding_backend;self.embedding_identity=embedding_identity
        self.reranker=reranker;self.settings=retrieval_settings or RetrievalSettings()
        from job_agent.resume_workspace.sqlite_code_indexes import SqliteCodeIndexRepository
        self.indexes=indexes or SqliteCodeIndexRepository(workspace,self.projects)

    def build(self,owner,project_id,snapshot,*,publish_guard=None,task_claim=None):
        if task_claim and task_claim.get('config_identity')!=self.indexing_config_identity:raise WorkspaceConflict('task_index_config_changed')
        started=perf_counter();files=self.projects.files(owner,project_id,snapshot)
        parsed=[parse_file(path,text) for path,text in sorted(files.items())]
        edges,unresolved=resolve_edges(parsed)
        symbols=[asdict(s) for p in parsed for s in p.symbols]
        chunks=[c for p in parsed for c in _chunks(snapshot,p.path,files[p.path],p)]
        if len(chunks)>12000 or len(symbols)>15000 or len(edges)>30000:raise WorkspaceConflict('code_index_quota_reached')
        manifest={path:sha256(text.encode()).hexdigest() for path,text in sorted(files.items())}
        # Expensive encoding happens before taking the publication transaction.
        # The same fencing guard publishes every derived artifact together.
        vector_artifact=None
        ast_chunks=sorted((c for c in chunks if c.metadata['granularity'] in ('ast','markdown')),key=lambda c:c.chunk_id)
        if self.embedding_backend is not None and ast_chunks:
            try:raw=self.embedding_backend.embed_documents([c.text for c in ast_chunks])
            except Exception as exc:raise WorkspaceConflict('code_embedding_backend_failed') from exc
            dimension=len(raw[0]) if raw else 0
            if len(raw)!=len(ast_chunks) or not 1<=dimension<=8192 or any(not valid_vector(v,dimension) for v in raw):
                raise WorkspaceConflict('code_vector_dimensions_or_values_invalid')
            try:spec=declared_identity(self.embedding_backend,self.embedding_identity).with_dimension(dimension)
            except ValueError as exc:raise WorkspaceConflict('code_vector_dimensions_or_values_invalid') from exc
            vector_manifest=manifest_for(ast_chunks,corpus_kind='code',scope=(owner,project_id,snapshot),
                parser_version=PARSER_VERSION,splitter_version=INDEX_VERSION,embedding=spec)
            vectors={c.chunk_id:list(v) for c,v in zip(ast_chunks,raw)}
            vector_artifact=(vector_manifest,dimension,encoded(vectors))
        report={'snapshot_id':snapshot,'index_version':INDEX_VERSION,'indexing_config_identity':self.indexing_config_identity,'file_manifest_hash':digest(manifest),
            'symbol_payload_hashes':{s['symbol_id']:sha256(encoded(s).encode()).hexdigest() for s in symbols},
            'chunk_payload_hashes':{c.chunk_id:sha256(c.model_dump_json().encode()).hexdigest() for c in chunks},
            'edges_hash':digest(sorted([{k:e[k] for k in ('source_id','target_id','kind','line')} for e in edges],key=lambda e:(e['source_id'],e['target_id'],e['kind'],e['line']))),
            'files':len(files),'symbols':len(symbols),'chunks':len(chunks),'edges':len(edges),'unresolved_references':unresolved,
            'file_status':{p.path:p.status for p in parsed},'warnings':{p.path:p.warnings for p in parsed if p.warnings},
            'oversized_lines_omitted':sum(len(line)>12000 for text in files.values() for line in text.splitlines(keepends=True)),
            'markdown_fragments':sum(c.metadata.get('structural_fragment',False) for c in chunks),
            'runtime_executed':False,'embedding_model':spec.model if vector_artifact else None,
            'vector_index_identity':vector_artifact[0].key if vector_artifact else None,
            'vector_manifest':asdict(vector_artifact[0]) if vector_artifact else None,
            'elapsed_ms':int((perf_counter()-started)*1000)}
        published=self.indexes.publish(owner,project_id,snapshot,report,symbols,chunks,edges,vector_artifact,
            publish_guard=publish_guard,task_claim=task_claim)
        return {**public_report(report),**(published or {}),'total_elapsed_ms':int((perf_counter()-started)*1000)}

    def status(self,owner,project_id,snapshot,*,_internal=False):
        row=self.indexes.report(owner,project_id,snapshot)
        return self._report_view(row,snapshot,_internal=_internal)

    def _report_view(self,row,snapshot,*,_internal=False):
        if row is None:return {'snapshot_id':snapshot,'status':'not_indexed','dense_available':False}
        if row['parser_version']!=INDEX_VERSION:
            return {'snapshot_id':snapshot,'status':'needs_rebuild','dense_available':self.embedding_backend is not None}
        if sha256(row['payload'].encode()).hexdigest()!=row['payload_hash']:raise WorkspaceConflict('code_index_integrity_failed')
        result=json.loads(row['payload'])
        return {**(result if _internal else public_report(result)),'status':'indexed','dense_available':self.embedding_backend is not None}

    def _load(self,owner,project_id,snapshot):
        stored=self.indexes.load(owner,project_id,snapshot)
        report=self._report_view(stored['report'],snapshot,_internal=True)
        if report.get('status')!='indexed':raise WorkspaceConflict('code_index_not_ready')
        rows=stored['symbols']
        if {r['symbol_id']:sha256(r['payload'].encode()).hexdigest() for r in rows}!=report['symbol_payload_hashes']:raise WorkspaceConflict('code_symbol_integrity_failed')
        symbols=[json.loads(r['payload']) for r in rows];chunks=[]
        for row in stored['chunks']:
            if sha256(row['payload'].encode()).hexdigest()!=row['payload_hash']:raise WorkspaceConflict('code_chunk_integrity_failed')
            chunks.append(KnowledgeChunk.model_validate_json(row['payload']))
        edges=stored['edges']
        if {c.chunk_id:sha256(c.model_dump_json().encode()).hexdigest() for c in chunks}!=report['chunk_payload_hashes']:raise WorkspaceConflict('code_chunk_manifest_changed')
        if digest(sorted(edges,key=lambda e:(e['source_id'],e['target_id'],e['kind'],e['line'])))!=report['edges_hash']:raise WorkspaceConflict('code_relation_integrity_failed')
        return report,symbols,chunks,edges

    @property
    def indexing_config_identity(self):
        return digest({'index_version':INDEX_VERSION,'embedding':asdict(declared_identity(self.embedding_backend,self.embedding_identity)) if self.embedding_backend else None})

    def citation_connection(self,db,workspace):
        # A SQLite resume transaction is never a PostgreSQL project transaction.
        return db if getattr(self.projects,'workspace',None) is workspace else None

    def read_code_range(self,owner,project_id,snapshot,path,start,end,*,method='read_code_range',db=None):
        if not 1<=start<=end or end-start>=120:raise WorkspaceConflict('code_line_range_limit')
        text,version=self.projects.read_file(owner,project_id,snapshot,path,db=db);lines=text.splitlines(keepends=True)
        if end>len(lines):raise WorkspaceConflict('code_line_range_invalid')
        quote=''.join(lines[start-1:end])
        if len(quote)>12000:raise WorkspaceConflict('code_range_character_limit')
        file_hash=sha256(text.encode()).hexdigest()
        key=f'{snapshot}:{path}:{start}:{end}:{file_hash}'
        kind='test_code' if is_test_path(path) else 'code' if path.casefold().endswith(('.py','.js','.jsx','.ts','.tsx','.sql')) else 'documentation'
        return EvidenceReference(evidence_id='ev-'+sha256(key.encode()).hexdigest()[:28],scope='private_project',owner_id=owner,
            project_id=project_id,snapshot_id=snapshot,source_id=snapshot+':'+path,content_hash=file_hash,path=path,
            start_line=start,end_line=end,commit=version['commit_sha'],retrieval_method=method,evidence_kind=kind,quote=quote)

    def validate_reference(self,owner,reference:EvidenceReference,*,db=None):
        if reference.scope!='private_project' or reference.owner_id!=owner or not reference.project_id:raise WorkspaceNotFound('reference_not_found')
        actual=self.read_code_range(owner,reference.project_id,reference.snapshot_id,reference.path,reference.start_line,reference.end_line,method=reference.retrieval_method,db=db)
        fields=('evidence_id','source_id','content_hash','commit','quote','evidence_kind')
        if any(getattr(actual,k)!=getattr(reference,k) for k in fields):raise WorkspaceConflict('code_reference_invalid')
        # Do not trust caller-supplied semantic support labels.
        return actual

    def get_symbol(self,owner,project_id,snapshot,name):
        _,symbols,_,_=self._load(owner,project_id,snapshot)
        found=[s for s in symbols if name in (s['symbol_id'],s['qualified_name'])]
        if not found:found=[s for s in symbols if s['name']==name]
        if not found:raise WorkspaceNotFound('code_symbol_not_found')
        if len(found)!=1:raise WorkspaceConflict('code_symbol_ambiguous_use_id_or_qualified_name')
        symbol=found[0];end=min(symbol['end_line'],symbol['start_line']+119)
        return {'symbol':symbol,'reference':self.read_code_range(owner,project_id,snapshot,symbol['path'],symbol['start_line'],end,method='get_symbol').model_dump(mode='json'),
                'truncated_to_line_budget':end<symbol['end_line'],'runtime_executed':False}

    def find_references(self,owner,project_id,snapshot,symbol_id,*,tests_only=False,limit=10):
        _,symbols,_,edges=self._load(owner,project_id,snapshot);lookup={s['symbol_id']:s for s in symbols}
        if symbol_id not in lookup:raise WorkspaceNotFound('code_symbol_not_found')
        result=[];seen=set()
        for edge in edges:
            if edge['target_id']!=symbol_id or edge['kind']=='import':continue
            source=lookup[edge['source_id']]
            if tests_only and not is_test_path(source['path']):continue
            key=(source['symbol_id'],edge['line'])
            if key in seen:continue
            seen.add(key);line=edge['line']
            result.append({'symbol':source,'relation':edge,'reference':self.read_code_range(owner,project_id,snapshot,source['path'],max(1,line-2),min(source['end_line'],line+2),method='get_test_evidence' if tests_only else 'find_references').model_dump(mode='json'),'test_execution':'not_run'})
            if len(result)>=max(1,min(limit,20)):break
        return result

    def _dense(self,owner,project_id,snapshot,chunks,query,limit):
        if self.embedding_backend is None:raise WorkspaceConflict('local_embedding_not_configured')
        if not chunks:return [],None
        # Resolve/validate the actual dimension before reading any old cache. Scope
        # has already been authenticated by _load; it is never a client filter.
        try:q=list(self.embedding_backend.embed_query(query))
        except Exception as exc:raise WorkspaceConflict('code_embedding_backend_failed') from exc
        if not valid_vector(q):raise WorkspaceConflict('code_query_vector_dimension_invalid')
        try:spec=declared_identity(self.embedding_backend,self.embedding_identity).with_dimension(len(q))
        except ValueError as exc:raise WorkspaceConflict('code_query_vector_dimension_invalid') from exc
        manifest=manifest_for(chunks,corpus_kind='code',scope=(owner,project_id,snapshot),
                              parser_version=PARSER_VERSION,splitter_version=INDEX_VERSION,embedding=spec)
        identity=manifest.key
        row=self.indexes.vector(owner,project_id,snapshot,identity)
        if row:
            if sha256(row['payload'].encode()).hexdigest()!=row['payload_hash']:raise WorkspaceConflict('code_vector_integrity_failed')
            vectors=json.loads(row['payload']);dimension=row['dimension']
            if set(vectors)!={c.chunk_id for c in chunks}:raise WorkspaceConflict('code_vector_manifest_changed')
        else:
            if getattr(self.embedding_backend,'require_prebuilt',False):
                raise WorkspaceConflict('code_dense_index_needs_rebuild')
            try:raw=self.embedding_backend.embed_documents([c.text for c in chunks])
            except Exception as exc:raise WorkspaceConflict('code_embedding_backend_failed') from exc
            if len(raw)!=len(chunks):raise WorkspaceConflict('code_vector_count_mismatch')
            dimension=len(raw[0]) if raw else 0;vectors={c.chunk_id:list(v) for c,v in zip(chunks,raw)}
        values=list(vectors.values())
        if dimension!=len(q) or any(not valid_vector(v,dimension) for v in values):
            raise WorkspaceConflict('code_vector_dimensions_or_values_invalid')
        if not row:
            payload=encoded(vectors)
            self.indexes.put_vector(owner,project_id,snapshot,identity,dimension,payload)
        index=InMemoryVectorIndex();index.add(chunks=chunks,vectors=[vectors[c.chunk_id] for c in chunks])
        return [r for r in index.search(query_vector=q,limit=limit) if r.score>0],identity

    def search(self,owner,project_id,request:CodeQuery):
        started=perf_counter();report,symbols,all_chunks,edges=self._load(owner,project_id,request.snapshot_id)
        granularity='flat' if request.method in ('flat','readme') else 'ast'
        chunks=[c for c in all_chunks if c.metadata['granularity']==granularity or (granularity=='ast' and c.metadata['granularity']=='markdown')]
        if request.method=='readme':chunks=[c for c in chunks if c.metadata['path'].casefold().endswith('readme.md')]
        lexical=BM25Index();lexical.add(chunks)
        depth=self.settings.sparse_candidates
        sparse=[r for r in lexical.search(query=request.query,limit=depth) if r.score>0]
        used=request.method;warnings=[];dense=[];manifest_key=None
        if request.method=='dense':
            dense,manifest_key=self._dense(owner,project_id,request.snapshot_id,chunks,request.query,self.settings.dense_candidates)
            ranked=dense
        elif request.method in ('hybrid','code_aware') and self.embedding_backend is not None:
            try:
                dense,manifest_key=self._dense(owner,project_id,request.snapshot_id,chunks,request.query,self.settings.dense_candidates)
            except WorkspaceConflict as exc:
                # Integrity errors are never hidden by a lexical fallback.
                if str(exc) not in ('code_dense_index_needs_rebuild','code_embedding_backend_failed'):raise
                warnings.append(str(exc));used='bm25_fallback'
            ranked=reciprocal_rank_fusion(dense_results=dense,bm25_results=sparse,
                limit=self.settings.fusion_candidates,k=self.settings.rrf_k) if dense else sparse
        else:
            ranked=sparse
            if request.method in ('hybrid','code_aware'):
                used='symbol_bm25_static_relations' if request.method=='code_aware' else 'bm25_fallback'
                warnings.append('semantic_embedding_not_configured; no_dense_recall_claim')
        ranked=ranked[:self.settings.fusion_candidates]
        fused_ids=[r.chunk.chunk_id for r in ranked]
        enabled=request.rerank if request.rerank is not None else (self.reranker is not None and request.method in ('hybrid','code_aware'))
        ranked,rerank_trace=apply_rerank(request.query,ranked,reranker=self.reranker,settings=self.settings,enabled=enabled)
        if rerank_trace['rerank_error']:warnings.append(rerank_trace['rerank_error'])
        if rerank_trace['rerank_applied']:used+='_rerank'
        selected=[];by_symbol={};by_id={s['symbol_id']:s for s in symbols}
        for c in chunks:
            if c.metadata.get('symbol_id'):by_symbol.setdefault(c.metadata['symbol_id'],[]).append(c)
        exact=[s for s in symbols if s['kind']!='module' and (
            re.search(r'(?<!\w)'+re.escape(s['qualified_name'])+r'(?!\w)',request.query,re.I) or
            re.search(r'(?<!\w)'+re.escape(s['name'])+r'(?!\w)',request.query,re.I))]
        exact.sort(key=lambda s:(-len(s['qualified_name']),s['path'],s['start_line']))
        if request.method in ('code_aware','symbol'):
            selected=[(c,1.0,'exact_symbol') for s in exact for c in by_symbol.get(s['symbol_id'],[])[:1]]
        if request.method!='symbol':selected.extend((r.chunk,r.score,r.retrieval_method) for r in ranked)
        unique={}
        for item in selected:unique.setdefault(item[0].chunk_id,item)
        selected=list(unique.values())[:self.settings.fusion_candidates]
        if request.method=='code_aware' and request.expand_relations and self.settings.relation_candidates:
            seeds=[c.metadata.get('symbol_id') for c,_,_ in selected[:min(2,request.limit)]]
            related=[];visited=set(seeds)
            for _ in range(2):
                next_ids=[]
                for e in edges:
                    adjacent=e['target_id'] if e['source_id'] in seeds else e['source_id'] if e['target_id'] in seeds else None
                    if adjacent and adjacent not in visited:
                        visited.add(adjacent);next_ids.append(adjacent)
                        for c in by_symbol.get(adjacent,[])[:1]:related.append((c,0.0,'static_'+e['kind']))
                    if len(related)>=self.settings.relation_candidates:break
                seeds=next_ids
                if not seeds or len(related)>=self.settings.relation_candidates:break
            # Preserve first relevant seed, then relation evidence before filler.
            selected=selected[:1]+related+selected[1:]
        budgeted,budget_trace=output_budget([RetrievedChunk(chunk=c,score=score,rank=i+1,retrieval_method=method)
            for i,(c,score,method) in enumerate(selected)],limit=request.limit,settings=self.settings)
        if budget_trace['budget_omitted_ids']:warnings.append('context_budget_omitted_whole_spans')
        hits=[];seen=set()
        for candidate in budgeted:
            c,score,method=candidate.chunk,candidate.score,candidate.retrieval_method
            m=c.metadata;key=(m['path'],m['start_line'],m['end_line'])
            if key in seen:continue
            seen.add(key)
            reference=self.read_code_range(owner,project_id,request.snapshot_id,m['path'],m['start_line'],m['end_line'],method=method)
            if reference.quote!=c.text or reference.content_hash!=c.document_content_hash:raise WorkspaceConflict('code_chunk_source_mismatch')
            hits.append({'reference':reference.model_dump(mode='json'),'symbol':by_id.get(m.get('symbol_id')),
                         'score':score,'retrieval_method':method,'support':'needs_judgment'})
            if len(hits)>=request.limit:break
        return {'hits':hits,'method_requested':request.method,'method_used':used,'warnings':warnings,
                'retrieval_trace':{'schema_version':'retrieval-trace-2','index_identity':manifest_key,
                    'config_identity':self.settings.key,**budget_trace,**rerank_trace,
                    'sparse_ids':[r.chunk.chunk_id for r in sparse], 'dense_ids':[r.chunk.chunk_id for r in dense],
                    'fused_ids':fused_ids, 'candidate_depth':depth,
                    'final_evidence_ids':[h['reference']['evidence_id'] for h in hits]},
                'index_version':INDEX_VERSION,'elapsed_ms':int((perf_counter()-started)*1000),
                'static_graph_only':True,'provider_calls':0,'embedding_calls':None if self.embedding_backend is not None else 0}


def install_code_routes(app,workspace,owner,service=None):
    service=service or CodeRAGService(workspace)
    @app.post('/api/v2/projects/{project_id}/index')
    def build(project_id:str,request:IndexRequest,user:str=Depends(owner)):return service.build(user,project_id,request.snapshot_id)
    @app.get('/api/v2/projects/{project_id}/index')
    def status(project_id:str,snapshot:str=Query(min_length=1,max_length=100),user:str=Depends(owner)):return service.status(user,project_id,snapshot)
    @app.post('/api/v2/projects/{project_id}/search')
    def search(project_id:str,request:CodeQuery,user:str=Depends(owner)):return service.search(user,project_id,request)
    @app.get('/api/v2/projects/{project_id}/symbol')
    def symbol(project_id:str,snapshot:str=Query(min_length=1,max_length=100),name:str=Query(min_length=1,max_length=200),user:str=Depends(owner)):return service.get_symbol(user,project_id,snapshot,name)
    @app.get('/api/v2/projects/{project_id}/references')
    def references(project_id:str,snapshot:str=Query(min_length=1,max_length=100),symbol_id:str=Query(min_length=1,max_length=100),tests_only:bool=False,user:str=Depends(owner)):return service.find_references(user,project_id,snapshot,symbol_id,tests_only=tests_only)
    @app.get('/api/v2/projects/{project_id}/code')
    def code(project_id:str,snapshot:str=Query(min_length=1,max_length=100),path:str=Query(min_length=1,max_length=240),start:int=Query(ge=1),end:int=Query(ge=1),user:str=Depends(owner)):return service.read_code_range(user,project_id,snapshot,path,start,end).model_dump(mode='json')
    return service

"""Static syntax extraction only. Never import/eval/execute inspected source."""
from __future__ import annotations
import ast
from dataclasses import dataclass,field,asdict
from hashlib import sha256
from pathlib import PurePosixPath
import posixpath
import re

PARSER_VERSION='code-syntax-v3-1'


def module_name(path):
    parts=list(PurePosixPath(path).with_suffix('').parts)
    if parts[-1]=='__init__':parts.pop()
    return '.'.join(parts)


def is_test_path(path):
    return bool(re.search(r'(^|/)(tests?|test_[^/]+)(/|\.)|\.(?:test|spec)\.[jt]sx?$',path,re.I))


@dataclass
class CodeSymbol:
    symbol_id:str
    path:str
    name:str
    qualified_name:str
    kind:str
    start_line:int
    end_line:int
    signature:str
    docstring:str
    language:str
    exported_as:list[str]=field(default_factory=list)


@dataclass
class RawReference:
    source_id:str
    target:str
    kind:str
    line:int


@dataclass
class ParsedFile:
    path:str
    status:str
    symbols:list[CodeSymbol]
    references:list[RawReference]
    warnings:list[str]=field(default_factory=list)


def _symbol(path,name,qualified,kind,start,end,signature,doc,language,exports=None):
    identity=f'{path}:{qualified}:{start}:{end}'
    return CodeSymbol('sym-'+sha256(identity.encode()).hexdigest()[:24],path,name,qualified,kind,start,end,signature[:1000],doc[:2000],language,exports or [])


def parse_python(path,text):
    module=_symbol(path,'<module>','<module>','module',1,max(1,len(text.splitlines())),path,'','python')
    try:tree=ast.parse(text,filename=path)
    except (SyntaxError,ValueError,RecursionError):return ParsedFile(path,'syntax_error_text',[module],[],['python_syntax_not_parsed'])
    symbols=[module];by_node={};stack=[]
    class Definitions(ast.NodeVisitor):
        def visit_ClassDef(self,node):
            self.define(node,'class')
        def visit_FunctionDef(self,node):self.define(node,'function')
        def visit_AsyncFunctionDef(self,node):self.define(node,'async_function')
        def define(self,node,kind):
            qualified='.'.join([*stack,node.name]);start=min([node.lineno,*[d.lineno for d in node.decorator_list]])
            signature=(('async ' if isinstance(node,ast.AsyncFunctionDef) else '')+'def '+node.name+'('+ast.unparse(node.args)+')') if kind!='class' else 'class '+node.name
            sym=_symbol(path,node.name,qualified,kind,start,node.end_lineno or node.lineno,signature,ast.get_docstring(node) or '','python')
            symbols.append(sym);by_node[id(node)]=sym;stack.append(node.name);self.generic_visit(node);stack.pop()
    try:Definitions().visit(tree)
    except RecursionError:return ParsedFile(path,'text_fallback',[module],[],['python_nesting_limit'])
    known={s.qualified_name:s for s in symbols};mod=module_name(path);refs=[]
    # Bindings assigned within a function shadow imports. Conservatively abstain
    # instead of guessing data flow or attributing obj.method to a same-name method.
    def local_bindings(node):
        result=set()
        class Bindings(ast.NodeVisitor):
            def visit_Name(self,n):
                if isinstance(n.ctx,(ast.Store,ast.Del)):result.add(n.id)
            def visit_FunctionDef(self,n):result.add(n.name)
            visit_AsyncFunctionDef=visit_FunctionDef
            def visit_ClassDef(self,n):result.add(n.name)
            def visit_Lambda(self,n):pass
        visitor=Bindings()
        for item in node.body:visitor.visit(item)
        args=node.args
        result.update(a.arg for a in [*args.posonlyargs,*args.args,*args.kwonlyargs])
        if args.vararg:result.add(args.vararg.arg)
        if args.kwarg:result.add(args.kwarg.arg)
        return result
    class References(ast.NodeVisitor):
        def __init__(self):self.scopes=[(module,{},set(),True)]
        def resolve(self,node):
            current,imports,locals_,self_binding_intact=self.scopes[-1]
            if isinstance(node,ast.Name):
                name=node.id
                if name in locals_:
                    nested=current.qualified_name+'.'+name
                    return mod+'.'+nested if nested in known else None
                if name in imports:return imports[name]
                context=current.qualified_name.split('.') if current.kind!='module' else []
                # In a function body, nested defs live below its qualified name.
                for n in range(len(context),-1,-1):
                    qualified='.'.join([*context[:n],name])
                    if qualified in known:return mod+'.'+qualified
                if name in locals_:return None
            if isinstance(node,ast.Attribute):
                parts=[];root=node
                while isinstance(root,ast.Attribute):parts.insert(0,root.attr);root=root.value
                if isinstance(root,ast.Name):
                    if root.id in imports:return imports[root.id]+'.'+'.'.join(parts)
                    if root.id in ('self','cls') and self_binding_intact:
                        parent=current.qualified_name.rsplit('.',1)[0]
                        if parent in known and known[parent].kind=='class':
                            return mod+'.'+parent+'.'+'.'.join(parts)
            return None
        def add(self,target,kind,line):
            if target:refs.append(RawReference(self.scopes[-1][0].symbol_id,target,kind,line))
        def visit_Import(self,node):
            for alias in node.names:
                local=alias.asname or alias.name.split('.')[0]
                target=alias.name if alias.asname else local
                self.scopes[-1][1][local]=target;self.add(alias.name,'import',node.lineno)
        def visit_ImportFrom(self,node):
            package=mod.split('.') if PurePosixPath(path).stem=='__init__' else mod.split('.')[:-1]
            target='.'.join(package[:max(0,len(package)-node.level+1)]+((node.module or '').split('.') if node.module else [])) if node.level else (node.module or '')
            for alias in node.names:
                if alias.name=='*':continue
                value=target+'.'+alias.name if target else alias.name
                self.scopes[-1][1][alias.asname or alias.name]=value;self.add(value,'import',node.lineno)
        def visit_FunctionDef(self,node):self.enter(node)
        visit_AsyncFunctionDef=visit_FunctionDef
        def visit_ClassDef(self,node):self.enter(node)
        def enter(self,node):
            current=self.scopes[-1];bindings=local_bindings(node) if isinstance(node,(ast.FunctionDef,ast.AsyncFunctionDef)) else set()
            imports={k:v for k,v in current[1].items() if k not in bindings}
            intact=not any(isinstance(n,ast.Name) and n.id in ('self','cls') and isinstance(n.ctx,ast.Store) for n in ast.walk(node))
            self.scopes.append((by_node[id(node)],imports,bindings,intact))
            # Decorators/defaults are not part of the body execution; skip rather
            # than assign misleading caller ownership to them.
            for item in node.body:self.visit(item)
            self.scopes.pop()
        def visit_Call(self,node):
            self.add(self.resolve(node.func),'call',node.lineno);self.generic_visit(node)
        def visit_Name(self,node):
            if isinstance(node.ctx,ast.Load):self.add(self.resolve(node),'reference',node.lineno)
    try:References().visit(tree)
    except RecursionError:return ParsedFile(path,'text_fallback',[module],[],['python_nesting_limit'])
    return ParsedFile(path,'python_ast',symbols,refs)


def parse_javascript(path,text):
    suffix=PurePosixPath(path).suffix.lower();language='typescript' if suffix in ('.ts','.tsx') else 'javascript'
    module=_symbol(path,'<module>','<module>','module',1,max(1,len(text.splitlines())),path,'',language)
    try:
        from tree_sitter import Language,Parser
        if language=='typescript':
            import tree_sitter_typescript as grammar
            lang=Language(grammar.language_tsx() if suffix=='.tsx' else grammar.language_typescript())
        else:
            import tree_sitter_javascript as grammar
            lang=Language(grammar.language())
        data=text.encode('utf-8');root=Parser(lang).parse(data).root_node
    except (ImportError,ValueError,TypeError):return ParsedFile(path,'text_fallback',[module],[],['tree_sitter_unavailable'])
    if root.has_error:return ParsedFile(path,'syntax_error_text',[module],[],['tree_sitter_syntax_error'])
    symbols=[module];nodes={};mod=module_name(path);imports={};refs=[]
    def content(node):return data[node.start_byte:node.end_byte].decode('utf-8') if node else ''
    def field(node,key):return node.child_by_field_name(key)
    def walk(node,parents=(),export_default=False):
        is_class=node.type in ('class_declaration','abstract_class_declaration')
        is_func=node.type in ('function_declaration','generator_function_declaration','method_definition')
        is_arrow=node.type=='variable_declarator' and field(node,'value') is not None and field(node,'value').type in ('arrow_function','function_expression')
        context=parents
        if is_class or is_func or is_arrow:
            name=content(field(node,'name'))
            if name:
                qualified='.'.join([*parents,name]);start=node.start_point.row+1
                end=node.end_point.row+(1 if node.end_point.column else 0)
                kind='class' if is_class else 'function'
                signature=content(node).split('{',1)[0].strip()
                sym=_symbol(path,name,qualified,kind,start,max(start,end),signature,'',language,
                            [mod+'.default'] if export_default else [])
                symbols.append(sym);nodes[node.id]=sym;context=(*parents,name)
        if node.type=='import_statement':
            source=content(field(node,'source')).strip('"\'')
            if source.startswith('.'):
                target=module_name(posixpath.normpath(posixpath.join(posixpath.dirname(path),source))) if PurePosixPath(source).suffix in ('.js','.jsx','.ts','.tsx') else posixpath.normpath(posixpath.join(posixpath.dirname(path),source)).replace('/','.')
                def import_nodes(n):
                    if n.type=='import_specifier':
                        original=content(field(n,'name'));alias=content(field(n,'alias')) or original
                        imports[alias]=target+'.'+original;refs.append(RawReference(module.symbol_id,target+'.'+original,'import',node.start_point.row+1));return
                    if n.type=='namespace_import':
                        names=[c for c in n.named_children if c.type=='identifier']
                        if names:imports[content(names[-1])]=target
                        return
                    if n.type=='import_clause':
                        for child in n.named_children:
                            if child.type=='identifier':imports[content(child)]=target+'.default'
                            else:import_nodes(child)
                        return
                    for child in n.named_children:import_nodes(child)
                import_nodes(node)
        is_default=node.type=='export_statement' and re.match(r'export\s+default\b',content(node)) is not None
        for child in node.named_children:walk(child,context,is_default)
    try:walk(root)
    except RecursionError:return ParsedFile(path,'text_fallback',[module],[],['javascript_nesting_limit'])
    known={s.qualified_name:s for s in symbols}
    assigned=set()
    def assignments(node):
        if node.type=='variable_declarator':
            target=field(node,'name')
            if target and target.type=='identifier':assigned.add(content(target))
        for child in node.named_children:assignments(child)
    assignments(root)
    def calls(node,current,shadow=frozenset()):
        current=nodes.get(node.id,current)
        if node.id in nodes and current.kind=='function':
            target_node=field(node,'value') if node.type=='variable_declarator' else node
            parameters=field(target_node,'parameters') or field(target_node,'parameter')
            shadow=shadow|set(re.findall(r'[A-Za-z_$][\w$]*',content(parameters)))
        if node.type=='call_expression':
            f=field(node,'function');name=content(f);target=None
            if f and f.type=='identifier':
                if name in imports and name not in shadow and name not in assigned:target=imports[name]
                elif name in shadow:target=None
                elif name in known:target=mod+'.'+name
                else:
                    prefix=current.qualified_name.rsplit('.',1)[0]
                    if prefix+'.'+name in known:target=mod+'.'+prefix+'.'+name
            elif f and f.type=='member_expression':
                obj=content(field(f,'object'));prop=content(field(f,'property'))
                if obj in imports and obj not in shadow and obj not in assigned:target=imports[obj]+'.'+prop
                elif obj=='this':
                    parent=current.qualified_name.rsplit('.',1)[0]
                    if parent in known and known[parent].kind=='class':target=mod+'.'+parent+'.'+prop
            if target:refs.append(RawReference(current.symbol_id,target,'call',node.start_point.row+1))
        for child in node.named_children:calls(child,current,shadow)
    try:calls(root,module)
    except RecursionError:return ParsedFile(path,'text_fallback',[module],[],['javascript_nesting_limit'])
    return ParsedFile(path,'tree_sitter',symbols,refs)


def parse_file(path,text):
    suffix=PurePosixPath(path).suffix.lower()
    try:
        if suffix=='.py':return parse_python(path,text)
        if suffix in {'.js','.jsx','.ts','.tsx'}:return parse_javascript(path,text)
    except RecursionError:return ParsedFile(path,'text_fallback',[],[],['syntax_nesting_limit'])
    return ParsedFile(path,'document',[],[])


def resolve_edges(parsed):
    """Only uniquely resolved full names, never basename guesses/dynamic calls."""
    lookup={}
    all_symbols={s.symbol_id:s for result in parsed for s in result.symbols}
    for sym in all_symbols.values():
        full=module_name(sym.path)+(('.'+sym.qualified_name) if sym.kind!='module' else '')
        for key in [full,*sym.exported_as]:lookup.setdefault(key,[]).append(sym)
    resolved_cache={}
    def candidates(target):
        if target in resolved_cache:return resolved_cache[target]
        exact=lookup.get(target,[])
        if exact:
            resolved_cache[target]={s.symbol_id:s for s in exact}
            return resolved_cache[target]
        matches={s.symbol_id:s for name,values in lookup.items() if name.endswith('.'+target) for s in values}
        resolved_cache[target]=matches
        return matches
    edges=[];seen=set();unresolved=0
    for result in parsed:
        for ref in result.references:
            found=candidates(ref.target)
            if len(found)!=1:unresolved+=1;continue
            target=next(iter(found.values()))
            if target.symbol_id==ref.source_id:continue
            key=(ref.source_id,target.symbol_id,ref.kind,ref.line)
            if key in seen:continue
            seen.add(key)
            edges.append({'source_id':ref.source_id,'target_id':target.symbol_id,'kind':ref.kind,'line':ref.line,
                          'certainty':'statically_resolved_reference','runtime_executed':False})
    return edges,unresolved

from __future__ import annotations

import hashlib
import json
import sqlite3
from contextlib import contextmanager
from datetime import UTC, datetime
from pathlib import Path
from typing import Iterator
from uuid import uuid4

from job_agent.resume_workspace.contracts import (
    ResumeCreate, ResumeDocument, ResumeSummary, SourceCreate, SourceRecord,
    VersionCreate, VersionRecord,
)


class WorkspaceNotFound(LookupError):
    """Missing and foreign-owned resources intentionally share one error."""


class WorkspaceConflict(ValueError):
    pass


class InvalidProvenance(ValueError):
    pass


_DDL = """
CREATE TABLE IF NOT EXISTS rw_sources (
    source_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, kind TEXT NOT NULL,
    label TEXT NOT NULL, text TEXT NOT NULL, content_hash TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS rw_sources_owner ON rw_sources(owner_id);
CREATE TABLE IF NOT EXISTS rw_resumes (
    resume_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, title TEXT NOT NULL,
    head_version_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS rw_resumes_owner ON rw_resumes(owner_id);
CREATE TABLE IF NOT EXISTS rw_versions (
    version_id TEXT PRIMARY KEY,
    resume_id TEXT NOT NULL REFERENCES rw_resumes(resume_id) ON DELETE CASCADE,
    sequence INTEGER NOT NULL, parent_version_id TEXT,
    restored_from_version_id TEXT, content_hash TEXT NOT NULL,
    document_json TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL,
    UNIQUE(resume_id, sequence)
);
CREATE TABLE IF NOT EXISTS rw_version_sources (
    version_id TEXT NOT NULL REFERENCES rw_versions(version_id) ON DELETE CASCADE,
    source_id TEXT NOT NULL REFERENCES rw_sources(source_id) ON DELETE RESTRICT,
    PRIMARY KEY(version_id, source_id)
);
CREATE TABLE IF NOT EXISTS rw_confirmations (
    version_id TEXT PRIMARY KEY REFERENCES rw_versions(version_id) ON DELETE CASCADE,
    content_hash TEXT NOT NULL, confirmed_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS rw_uploads (
    source_id TEXT PRIMARY KEY REFERENCES rw_sources(source_id) ON DELETE CASCADE,
    filename TEXT NOT NULL, raw_hash TEXT NOT NULL, raw_bytes BLOB NOT NULL,
    metadata_json TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS rw_drafts (
    draft_id TEXT PRIMARY KEY, owner_id TEXT NOT NULL,
    source_id TEXT NOT NULL REFERENCES rw_sources(source_id) ON DELETE RESTRICT,
    payload_json TEXT NOT NULL, payload_hash TEXT NOT NULL,
    accepted_resume_id TEXT REFERENCES rw_resumes(resume_id) ON DELETE CASCADE,
    accepted_version_id TEXT, accepted_request_hash TEXT
);
CREATE INDEX IF NOT EXISTS rw_drafts_owner ON rw_drafts(owner_id);
"""


def _now() -> str:
    return datetime.now(UTC).isoformat()


def _encoded(document: ResumeDocument) -> str:
    return json.dumps(document.model_dump(mode="json"), sort_keys=True,
                      ensure_ascii=False, separators=(",", ":"))


class SqliteResumeRepository:
    """Single-machine product store; one connection per transaction.

    No global connection crosses FastAPI threads. BEGIN IMMEDIATE serializes
    check-and-append operations, and the expected head prevents lost edits.
    This does not implement the existing PostgreSQL/Redis worker protocol.
    """

    def __init__(self, path: str | Path):
        self.path = Path(path).resolve()
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self._connection() as db:
            db.executescript(_DDL)

    @contextmanager
    def _connection(self, *, write: bool = False) -> Iterator[sqlite3.Connection]:
        db = sqlite3.connect(self.path, timeout=10)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA foreign_keys = ON")
        try:
            db.execute("BEGIN IMMEDIATE" if write else "BEGIN")
            yield db
            db.commit()
        except BaseException:
            db.rollback()
            raise
        finally:
            db.close()

    def add_source(self, owner_id: str, request: SourceCreate) -> SourceRecord:
        with self._connection(write=True) as db:
            return self._insert_source(db, owner_id, request)

    @staticmethod
    def _insert_source(db, owner_id: str, request: SourceCreate) -> SourceRecord:
        # Revalidation prevents callers from bypassing normalization via model_copy.
        request = SourceCreate.model_validate(request.model_dump())
        source = SourceRecord(
            **request.model_dump(), source_id=f"src-{uuid4().hex}",
            content_hash=hashlib.sha256(request.text.encode("utf-8")).hexdigest(),
            created_at=datetime.now(UTC),
        )
        db.execute("INSERT INTO rw_sources VALUES (?, ?, ?, ?, ?, ?, ?)",
                   (source.source_id, owner_id, source.kind, source.label, source.text,
                    source.content_hash, source.created_at.isoformat()))
        return source

    @staticmethod
    def _source(db, owner_id: str, source_id: str) -> SourceRecord:
        row = db.execute("SELECT * FROM rw_sources WHERE source_id=? AND owner_id=?",
                         (source_id, owner_id)).fetchone()
        if row is None:
            raise WorkspaceNotFound("source_not_found")
        payload = dict(row)
        payload.pop("owner_id")
        source = SourceRecord.model_validate(payload)
        if hashlib.sha256(source.text.encode("utf-8")).hexdigest() != source.content_hash:
            raise InvalidProvenance("source_integrity_failed")
        return source

    def get_source(self, owner_id: str, source_id: str) -> SourceRecord:
        with self._connection() as db:
            return self._source(db, owner_id, source_id)

    def list_sources(self, owner_id: str):
        from job_agent.resume_workspace.contracts import SourceSummary
        with self._connection() as db:
            rows = db.execute(
                "SELECT s.source_id,s.kind,s.label,s.created_at, "
                "(EXISTS(SELECT 1 FROM rw_version_sources v WHERE v.source_id=s.source_id) OR "
                "EXISTS(SELECT 1 FROM rw_drafts d WHERE d.source_id=s.source_id)) AS referenced, "
                "EXISTS(SELECT 1 FROM rw_uploads u WHERE u.source_id=s.source_id) AS has_original "
                "FROM rw_sources s WHERE s.owner_id=? ORDER BY s.created_at DESC LIMIT 200", (owner_id,)
            ).fetchall()
            return [SourceSummary.model_validate(dict(row)) for row in rows]

    @staticmethod
    def _resume(db, owner_id: str, resume_id: str):
        row = db.execute("SELECT * FROM rw_resumes WHERE resume_id=? AND owner_id=?",
                         (resume_id, owner_id)).fetchone()
        if row is None:
            raise WorkspaceNotFound("resume_not_found")
        return row

    def _validate_document(self, db, owner_id: str, document: ResumeDocument) -> ResumeDocument:
        document = ResumeDocument.model_validate(document.model_dump())
        self._validate_draft_facts(db, owner_id, document)
        return document

    @staticmethod
    def _version(db, resume_id: str, version_id: str) -> VersionRecord:
        row = db.execute(
            "SELECT v.*, c.confirmed_at FROM rw_versions v LEFT JOIN rw_confirmations c "
            "ON v.version_id=c.version_id WHERE v.resume_id=? AND v.version_id=?",
            (resume_id, version_id),
        ).fetchone()
        if row is None:
            raise WorkspaceNotFound("version_not_found")
        payload = dict(row)
        encoded = payload.pop("document_json")
        document = ResumeDocument.model_validate_json(encoded)
        if hashlib.sha256(_encoded(document).encode("utf-8")).hexdigest() != payload["content_hash"]:
            raise InvalidProvenance("version_integrity_failed")
        return VersionRecord(**payload, document=document)

    def _append(self, db, owner_id: str, resume_id: str, document: ResumeDocument, *,
                sequence: int, parent: str | None, note: str, restored_from: str | None = None):
        document = self._validate_document(db, owner_id, document)
        encoded = _encoded(document)
        version_id = f"ver-{uuid4().hex}"
        now = _now()
        db.execute("INSERT INTO rw_versions VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                   (version_id, resume_id, sequence, parent, restored_from,
                    hashlib.sha256(encoded.encode("utf-8")).hexdigest(), encoded, note, now))
        db.executemany("INSERT INTO rw_version_sources VALUES (?, ?)",
                       [(version_id, source_id) for source_id in
                        sorted({fact.source.source_id for fact in document.facts()})])
        db.execute("UPDATE rw_resumes SET head_version_id=?, updated_at=? WHERE resume_id=?",
                   (version_id, now, resume_id))
        return self._version(db, resume_id, version_id)

    def create_resume(self, owner_id: str, request: ResumeCreate) -> VersionRecord:
        request = ResumeCreate.model_validate(request.model_dump())
        resume_id = f"res-{uuid4().hex}"
        with self._connection(write=True) as db:
            now = _now()
            db.execute("INSERT INTO rw_resumes VALUES (?, ?, ?, '', ?, ?)",
                       (resume_id, owner_id, request.title, now, now))
            return self._append(db, owner_id, resume_id, request.document,
                                sequence=1, parent=None, note="initial")

    def list_resumes(self, owner_id: str) -> list[ResumeSummary]:
        with self._connection() as db:
            rows = db.execute(
                "SELECT r.*, (SELECT COUNT(*) FROM rw_versions v WHERE v.resume_id=r.resume_id) "
                "AS version_count FROM rw_resumes r WHERE owner_id=? ORDER BY updated_at DESC, resume_id",
                (owner_id,),
            ).fetchall()
            return [ResumeSummary.model_validate({k: row[k] for k in ResumeSummary.model_fields})
                    for row in rows]

    def get_version(self, owner_id: str, resume_id: str, version_id: str) -> VersionRecord:
        with self._connection() as db:
            self._resume(db, owner_id, resume_id)
            version = self._version(db, resume_id, version_id)
            self._validate_document(db, owner_id, version.document)
            return version

    def list_versions(self, owner_id: str, resume_id: str) -> list[VersionRecord]:
        with self._connection() as db:
            self._resume(db, owner_id, resume_id)
            ids = db.execute("SELECT version_id FROM rw_versions WHERE resume_id=? ORDER BY sequence DESC",
                             (resume_id,)).fetchall()
            versions = [self._version(db, resume_id, row[0]) for row in ids]
            for version in versions:
                self._validate_document(db, owner_id, version.document)
            return versions

    def save_version(self, owner_id: str, resume_id: str, request: VersionCreate) -> VersionRecord:
        request = VersionCreate.model_validate(request.model_dump())
        with self._connection(write=True) as db:
            resume = self._resume(db, owner_id, resume_id)
            if resume["head_version_id"] != request.expected_parent_version_id:
                raise WorkspaceConflict("resume_head_changed")
            previous = self._version(db, resume_id, request.expected_parent_version_id)
            return self._append(db, owner_id, resume_id, request.document,
                                sequence=previous.sequence + 1, parent=previous.version_id, note=request.note)

    def confirm_version(self, owner_id: str, resume_id: str, version_id: str, *,
                        expected_content_hash: str) -> VersionRecord:
        with self._connection(write=True) as db:
            resume = self._resume(db, owner_id, resume_id)
            version = self._version(db, resume_id, version_id)
            if version.content_hash != expected_content_hash:
                raise WorkspaceConflict("confirmation_content_changed")
            self._validate_document(db, owner_id, version.document)
            if version.confirmed_at is not None:
                # A repeated confirmation remains idempotent after later edits.
                return version
            if resume["head_version_id"] != version_id:
                raise WorkspaceConflict("only_current_version_can_be_confirmed")
            db.execute("INSERT INTO rw_confirmations VALUES (?, ?, ?)",
                       (version_id, version.content_hash, _now()))
            return self._version(db, resume_id, version_id)

    def restore_version(self, owner_id: str, resume_id: str, version_id: str, *,
                        expected_parent_version_id: str, note: str = "") -> VersionRecord:
        # Reuse the input contract even when called outside HTTP.
        from job_agent.resume_workspace.contracts import RestoreVersion

        request = RestoreVersion(expected_parent_version_id=expected_parent_version_id, note=note)
        with self._connection(write=True) as db:
            resume = self._resume(db, owner_id, resume_id)
            if resume["head_version_id"] != request.expected_parent_version_id:
                raise WorkspaceConflict("resume_head_changed")
            previous = self._version(db, resume_id, resume["head_version_id"])
            original = self._version(db, resume_id, version_id)
            return self._append(db, owner_id, resume_id, original.document,
                                sequence=previous.sequence + 1, parent=previous.version_id,
                                note=request.note, restored_from=version_id)

    def delete_resume(self, owner_id: str, resume_id: str) -> None:
        with self._connection(write=True) as db:
            self._resume(db, owner_id, resume_id)
            db.execute("DELETE FROM rw_resumes WHERE resume_id=? AND owner_id=?", (resume_id, owner_id))

    def delete_source(self, owner_id: str, source_id: str) -> None:
        with self._connection(write=True) as db:
            self._source(db, owner_id, source_id)
            used = db.execute("SELECT 1 FROM rw_version_sources WHERE source_id=? LIMIT 1", (source_id,)).fetchone()
            if used:
                raise WorkspaceConflict("source_referenced_by_version")
            if db.execute("SELECT 1 FROM rw_drafts WHERE source_id=?", (source_id,)).fetchone():
                raise WorkspaceConflict("source_referenced_by_draft")
            db.execute("DELETE FROM rw_sources WHERE source_id=? AND owner_id=?", (source_id, owner_id))

    def save_upload(self, owner_id: str, *, filename: str, data: bytes, extracted):
        from job_agent.resume_workspace.parsing_contracts import UploadView
        filename = Path(filename.replace("\\", "/")).name[:120]
        raw_hash = hashlib.sha256(data).hexdigest()
        with self._connection(write=True) as db:
            source = self._insert_source(db, owner_id, SourceCreate(
                kind="original_resume", label=filename or "上传简历", text=extracted.text))
            db.execute("INSERT INTO rw_uploads VALUES (?, ?, ?, ?, ?)",
                       (source.source_id, filename, raw_hash, data, json.dumps(extracted.metadata)))
        return UploadView(source_id=source.source_id, content_hash=source.content_hash,
                          filename=filename, raw_hash=raw_hash, byte_size=len(data),
                          parser=str(extracted.metadata["parser"]), source_format=str(extracted.metadata["source_format"]))

    def get_upload(self, owner_id: str, source_id: str):
        with self._connection() as db:
            self._source(db, owner_id, source_id)
            row = db.execute("SELECT * FROM rw_uploads WHERE source_id=?", (source_id,)).fetchone()
            if row is None:
                raise WorkspaceNotFound("upload_not_found")
            data = bytes(row["raw_bytes"])
            if hashlib.sha256(data).hexdigest() != row["raw_hash"]:
                raise InvalidProvenance("upload_integrity_failed")
            return row["filename"], data

    def save_draft(self, owner_id: str, draft):
        from job_agent.resume_workspace.parsing_contracts import DraftRecord
        draft = DraftRecord.model_validate(draft.model_dump())
        payload = draft.model_dump_json()
        with self._connection(write=True) as db:
            source = self._source(db, owner_id, draft.source_id)
            if source.content_hash != draft.source_content_hash or source.kind != "original_resume":
                raise InvalidProvenance("draft_source_mismatch")
            if any(f.source.source_id != source.source_id for f in draft.document.facts()):
                raise InvalidProvenance("draft_source_mismatch")
            # Drafts may miss required identity/entry fields, but every present fact is checked.
            self._validate_draft_facts(db, owner_id, draft.document)
            db.execute("INSERT INTO rw_drafts VALUES (?, ?, ?, ?, ?, NULL, NULL, NULL)",
                       (draft.draft_id, owner_id, draft.source_id, payload,
                        hashlib.sha256(payload.encode()).hexdigest()))
        return draft

    def _validate_draft_facts(self, db, owner_id, document):
        # Reuse the authoritative provenance check; a draft's missing required
        # fields cannot be revalidated as a complete ResumeDocument yet.
        sources = {}
        for fact in document.facts():
            if fact.source.source_id not in sources:
                sources[fact.source.source_id] = self._source(db, owner_id, fact.source.source_id)
            source = sources[fact.source.source_id]
            if source.kind not in {"original_resume", "user_statement"}:
                raise InvalidProvenance("reference_or_jd_is_not_candidate_evidence")
            if source.content_hash != fact.source.content_hash:
                raise InvalidProvenance("source_hash_mismatch")
            if fact.source.end > len(source.text) or source.text[fact.source.start:fact.source.end] != fact.text:
                raise InvalidProvenance("fact_quote_mismatch")

    def _draft(self, db, owner_id: str, draft_id: str):
        from job_agent.resume_workspace.parsing_contracts import DraftRecord
        row = db.execute("SELECT * FROM rw_drafts WHERE draft_id=? AND owner_id=?", (draft_id, owner_id)).fetchone()
        if row is None:
            raise WorkspaceNotFound("draft_not_found")
        if hashlib.sha256(row["payload_json"].encode()).hexdigest() != row["payload_hash"]:
            raise InvalidProvenance("draft_integrity_failed")
        draft = DraftRecord.model_validate_json(row["payload_json"])
        source = self._source(db, owner_id, draft.source_id)
        if source.content_hash != draft.source_content_hash:
            raise InvalidProvenance("draft_source_mismatch")
        self._validate_draft_facts(db, owner_id, draft.document)
        return draft.model_copy(update={"accepted_resume_id": row["accepted_resume_id"],
                                        "accepted_version_id": row["accepted_version_id"]}), row

    def get_draft(self, owner_id: str, draft_id: str):
        with self._connection() as db:
            return self._draft(db, owner_id, draft_id)[0]

    def list_drafts(self, owner_id: str):
        with self._connection() as db:
            ids = db.execute("SELECT draft_id FROM rw_drafts WHERE owner_id=? AND accepted_resume_id IS NULL "
                             "ORDER BY rowid DESC LIMIT 100", (owner_id,)).fetchall()
            return [self._draft(db, owner_id, row[0])[0] for row in ids]

    def delete_draft(self, owner_id: str, draft_id: str):
        with self._connection(write=True) as db:
            self._draft(db, owner_id, draft_id)
            db.execute("DELETE FROM rw_drafts WHERE draft_id=? AND owner_id=?", (draft_id, owner_id))

    def _apply_edits(self, db, owner_id, document, edits):
        from job_agent.resume_workspace.fields import checked_path, compact, set_field
        from job_agent.resume_workspace.parsing_contracts import ParseError
        from job_agent.text_identity import normalize_text
        payload = document.model_dump(mode="json")
        paths = set()
        clean = []
        for edit in edits:
            checked_path(edit.path)
            if edit.path in paths:
                raise ParseError("duplicate_field_path")
            paths.add(edit.path)
            clean.append((edit.path, normalize_text(edit.value).strip()))
        # One immutable self-attestation for the explicit edit operation.
        statement = "\n\n".join(f"{path}：{value}" for path, value in clean if value)
        if len(statement) > 100_000:
            raise ParseError("user_edits_too_large")
        source = self._insert_source(db, owner_id, SourceCreate(kind="user_statement", label="人工核对补充",
                                                               text=statement)) if statement else None
        cursor = 0
        for path, value in clean:
            fact = None
            if value:
                start = source.text.index(f"{path}：{value}", cursor) + len(path) + 1
                cursor = start + len(value)
                fact = {"fact_id": "f-" + uuid4().hex[:20], "text": value, "source": {
                    "source_id": source.source_id, "content_hash": source.content_hash,
                    "start": start, "end": start + len(value)}}
            set_field(payload, path, fact)
        try:
            return ResumeDocument.model_validate(compact(payload))
        except ValueError as exc:
            raise ParseError("required_fields_missing") from exc

    def accept_draft(self, owner_id: str, draft_id: str, request):
        from job_agent.resume_workspace.parsing_contracts import AcceptDraft
        request = AcceptDraft.model_validate(request.model_dump())
        encoded = json.dumps({**request.model_dump(), "edits": sorted(
            [item.model_dump() for item in request.edits], key=lambda x: x["path"])}, sort_keys=True, ensure_ascii=False)
        request_hash = hashlib.sha256(encoded.encode()).hexdigest()
        with self._connection(write=True) as db:
            draft, row = self._draft(db, owner_id, draft_id)
            if request.expected_source_hash != draft.source_content_hash:
                raise WorkspaceConflict("draft_source_changed")
            if row["accepted_resume_id"]:
                if row["accepted_request_hash"] != request_hash:
                    raise WorkspaceConflict("draft_already_accepted")
                return self._version(db, row["accepted_resume_id"], row["accepted_version_id"])
            document = self._apply_edits(db, owner_id, draft.document, request.edits)
            resume_id = "res-" + uuid4().hex
            now = _now()
            db.execute("INSERT INTO rw_resumes VALUES (?, ?, ?, '', ?, ?)",
                       (resume_id, owner_id, request.title, now, now))
            version = self._append(db, owner_id, resume_id, document, sequence=1, parent=None, note="核对解析草稿")
            db.execute("UPDATE rw_drafts SET accepted_resume_id=?, accepted_version_id=?, accepted_request_hash=? "
                       "WHERE draft_id=?", (resume_id, version.version_id, request_hash, draft_id))
            return version

    def edit_version(self, owner_id: str, resume_id: str, version_id: str, request):
        from job_agent.resume_workspace.parsing_contracts import EditVersion
        request = EditVersion.model_validate(request.model_dump())
        with self._connection(write=True) as db:
            resume = self._resume(db, owner_id, resume_id)
            if resume["head_version_id"] != version_id:
                raise WorkspaceConflict("resume_head_changed")
            original = self._version(db, resume_id, version_id)
            document = self._apply_edits(db, owner_id, original.document, request.edits)
            return self._append(db, owner_id, resume_id, document, sequence=original.sequence + 1,
                                parent=version_id, note=request.note)

"""Relative C1 assertion audit. Neither a truth detector nor a semantic oracle."""
from __future__ import annotations
import re
from typing import Literal
from pydantic import Field
from job_agent.schemas import StrictModel
from job_agent.resume_workspace.execution_state import state_hash


class ReviewedClaim(StrictModel):
    text:str=Field(min_length=1,max_length=5000)
    source_quote:str=Field(default='',max_length=5000)
    status:Literal['supported','unsupported','contradicted','uncertain']
    reason:str=Field(min_length=1,max_length=300)


class AuditedClaim(StrictModel):
    claim_id:str
    text:str
    start:int
    end:int
    kinds:list[str]
    change:Literal['unchanged_or_controlled_paraphrase','new_or_semantic_change']
    status:Literal['supported','unsupported','contradicted','uncertain']
    assessed_by:Literal['deterministic_alignment','deterministic_gate','model_semantic_unverified','not_assessed']
    source_id:str|None=None
    source_quote:str|None=None
    reason:str


class ClaimAudit(StrictModel):
    source_hash:str
    draft_hash:str
    claims:list[AuditedClaim]
    hard_issues:list[str]
    unresolved_ids:list[str]
    acceptable:bool
    semantic_truth:Literal['not_independently_verified']='not_independently_verified'


OUTCOMES={
    'success_rate':r'求职成功率|成功率|录用率|面试通过率|获得录用|获得offer',
    'throughput':r'吞吐|\bQPS\b|每秒处理',
    'latency':r'延迟|时延|响应时间|响应速度|耗时|等待时间',
    'accuracy':r'准确率|正确率|精确率|召回率',
    'coverage':r'测试覆盖率|覆盖率',
    'cost':r'成本|费用',
    'users':r'用户量|活跃用户|留存率',
    'duplicate_reads':r'重复读取|重复读|重复查询',
    'duplicate_writes':r'重复写入|重复写|重复提交|重复执行',
    'tests_passed':r'测试.{0,6}(?:已|均|全部|成功)?通过|通过了(?:全部|所有|全量)?测试',
    'award':r'获奖|一等奖|二等奖|三等奖|冠军|国家级|全国',
    'production_result':r'线上稳定|稳定运行|零故障|零错误|线上可用',
}
EFFECT=r'提高|提升|降低|减少|缩短|增加|改善|优化|避免|消除|加快|显著|大幅|达到|促成|带来'
NEG=r'尚未|没有|从未|未使用|未部署|未上线|未运行|尚无|不负责|\bnot\b|\bnever\b|\bwithout\b'


def parts(text):
    return [(m.start()+len(m.group())-len(m.group().lstrip()),m.start()+len(m.group().rstrip()),m.group().strip())
        for m in re.finditer(r'[^，,。；;\n]+[，,。；;]?',text) if m.group().strip()]


def controlled(text):
    text=re.sub(r'^我参与了','参与',text);text=re.sub(r'^我使用','使用',text)
    text=text.replace('基于','使用').replace('实现','开发')
    return re.sub(r'[\s，,。；;]','',text)


def outcome_types(text):
    return {k for k,p in OUTCOMES.items() if re.search(p,text,re.I)}


def entities(text):
    return {w.rstrip('.-').casefold() for w in re.findall(r'[A-Za-z][A-Za-z0-9_+#.\-]*',text)}


def additional_hard_issues(original,proposed):
    issues=[]
    new_outcomes=outcome_types(proposed)-outcome_types(original)
    if re.search(EFFECT,proposed) or new_outcomes & {'tests_passed','award','production_result'}:
        for kind in sorted(new_outcomes):
            issues.append('新增无原文依据成果：'+kind)
    for degree in ('显著','大幅','彻底','完全消除','百分之百'):
        if degree in proposed and degree not in original:issues.append('新增成果强度：'+degree)
    if re.search(r'因此|从而|使得|促成|带来',proposed) and not re.search(r'因此|从而|使得|促成|带来',original):
        issues.append('新增因果归因，需要原始依据')
    negative=set();positive=set()
    for _,_,text in parts(original):
        target=negative if re.search(NEG,text,re.I) else positive
        target.update(entities(text))
    for _,_,text in parts(proposed):
        if re.search(NEG,text,re.I):continue
        positive_entities=entities(text)
        if positive_entities & (negative-positive):issues.append('与原文否定实体冲突：'+','.join(sorted(positive_entities & (negative-positive))))
    return list(dict.fromkeys(issues))


def deterministic_hard_issues(original,proposed):
    issues=[]
    if set(re.findall(r'\d+(?:\.\d+)?%?',proposed))-set(re.findall(r'\d+(?:\.\d+)?%?',original)):
        issues.append('新增或改变数字/年限')
    if entities(proposed)-entities(original):
        issues.append('新增英文技术/实体')
    for word in ('未独立','尚未','没有','尚无','未使用','未部署','不负责','非生产','参与','协助','原型','课程','本地','实验','模拟'):
        if word in original and word not in proposed:issues.append('删除否定或范围限定：'+word)
    for word in ('not','never','without','prototype','assisted','coursework','local'):
        if re.search(r'\b'+word+r'\b',original,re.I) and not re.search(r'\b'+word+r'\b',proposed,re.I):
            issues.append('删除英文否定或范围限定：'+word)
    for word in ('独立负责','主导','精通','专家','生产环境','生产级','大规模','端到端负责','领导'):
        if word in proposed and word not in original:issues.append('扩大职责/能力：'+word)
    return [*issues,*additional_hard_issues(original,proposed)]


def audit_claims(original,proposed,*,reviews=(),context=None,source_id='source_fact',hard_issues=()):
    hard=list(dict.fromkeys([*hard_issues,*deterministic_hard_issues(original,proposed)]))
    source_parts=[(text,source_id) for _,_,text in parts(original)]
    context=context or {}
    source_parts += [(str(text),'entry_context.'+key) for key,text in context.items() if key in ('name','organization','role','period')]
    reviewed={r.text:r for r in [ReviewedClaim.model_validate(r) for r in reviews]}
    claims=[]
    for start,end,text in parts(proposed):
        kinds=[]
        for kind,pattern in [('responsibility',r'负责|参与|主导|协助|领导'),('technology',r'[A-Za-z][A-Za-z0-9_+#.\-]*'),
            ('quantity',r'\d'),('time',r'年|月|期间'),('outcome',EFFECT),('causality',r'因此|从而|使得|促成|带来'),('scope',r'本地|原型|生产|实验|课程|尚未|没有')]:
            if re.search(pattern,text):kinds.append(kind)
        aligned=next(((q,key) for q,key in source_parts if controlled(q)==controlled(text)),None)
        item=AuditedClaim(claim_id='claim-'+state_hash([start,end,text])[:24],text=text,start=start,end=end,kinds=kinds or ['statement'],
            change='unchanged_or_controlled_paraphrase' if aligned else 'new_or_semantic_change',
            status='supported' if aligned else 'uncertain',assessed_by='deterministic_alignment' if aligned else 'not_assessed',
            source_id=aligned[1] if aligned else None,source_quote=aligned[0] if aligned else None,
            reason='与C1分句相等或受限措辞转换；未独立核实。' if aligned else '尚无逐断言语义审查或来源映射。')
        review=reviewed.get(text)
        if not aligned and review:
            anchors=[(original,source_id),*[(str(v),'entry_context.'+k) for k,v in context.items() if k in ('name','organization','role','period')]]
            anchor=next(((q,k) for q,k in anchors if review.source_quote and review.source_quote in q),None)
            item.status=review.status if anchor or review.status!='supported' else 'uncertain'
            item.assessed_by='model_semantic_unverified';item.source_quote=review.source_quote or None
            item.source_id=anchor[1] if anchor else None;item.reason=review.reason if anchor else '模型未提供有效C1原文摘录，不能认定支持。'
        clause_issues=additional_hard_issues(original,text)
        if clause_issues:
            item.status='contradicted' if any('否定实体冲突' in issue for issue in clause_issues) else 'unsupported'
            item.assessed_by='deterministic_gate';item.reason='程序门禁：'+'；'.join(clause_issues)
        claims.append(item)
    unresolved=[c.claim_id for c in claims if c.status!='supported']
    return ClaimAudit(source_hash=state_hash(original),draft_hash=state_hash(proposed),claims=claims,hard_issues=hard,
        unresolved_ids=unresolved,acceptable=bool(claims) and not hard and not unresolved)

from __future__ import annotations

import io
from pathlib import Path
from tempfile import TemporaryDirectory
import zipfile

from job_agent.knowledge.source_loader import load_source
from job_agent.resume_workspace.parsing_contracts import ImportErrorCode


MAX_UPLOAD_BYTES = 5 * 1024 * 1024


def extract_upload(filename: str, data: bytes):
    """No client-controlled paths, archive extraction or external OCR calls."""
    suffix = Path(filename.replace("\\", "/")).suffix.lower()
    if suffix not in {".txt", ".md", ".pdf", ".docx"}:
        raise ImportErrorCode("unsupported_file_type")
    if not data:
        raise ImportErrorCode("empty_upload")
    if len(data) > MAX_UPLOAD_BYTES:
        raise ImportErrorCode("upload_too_large")
    if suffix == ".pdf":
        if not data.startswith(b"%PDF-"):
            raise ImportErrorCode("invalid_pdf")
        try:
            from pypdf import PdfReader
            reader = PdfReader(io.BytesIO(data))
            if reader.is_encrypted:
                raise ImportErrorCode("encrypted_pdf")
            if len(reader.pages) > 40:
                raise ImportErrorCode("too_many_pages")
        except ImportErrorCode:
            raise
        except Exception as exc:
            raise ImportErrorCode("invalid_pdf") from exc
    if suffix == ".docx":
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as archive:
                files = archive.infolist()
                if len(files) > 2000 or sum(item.file_size for item in files) > 30 * 1024 * 1024:
                    raise ImportErrorCode("expanded_document_too_large")
                if "word/document.xml" not in archive.namelist():
                    raise ImportErrorCode("invalid_docx")
                if any(item.flag_bits & 1 for item in files):
                    raise ImportErrorCode("encrypted_docx")
        except (zipfile.BadZipFile, RuntimeError) as exc:
            raise ImportErrorCode("invalid_docx") from exc
    with TemporaryDirectory(prefix="resume-import-") as directory:
        path = Path(directory) / ("upload" + suffix)
        path.write_bytes(data)
        try:
            result = load_source(path)
        except ValueError as exc:
            code = "needs_ocr" if suffix == ".pdf" and "no extractable text" in str(exc).lower() else "document_extraction_failed"
            raise ImportErrorCode(code) from exc
    if len(result.text) > 100_000:
        raise ImportErrorCode("extracted_text_too_large")
    return result

"""Pure bounded archive scanning. Imported projects are DATA, never executed."""
from __future__ import annotations
from hashlib import sha256
from io import BytesIO
from pathlib import PurePosixPath
import re
import stat
import unicodedata
from zipfile import ZipFile, BadZipFile
from job_agent.resume_workspace.repository import WorkspaceConflict

MAX_ARCHIVE_BYTES=8*1024*1024
MAX_EXPANDED_BYTES=24*1024*1024
MAX_FILE_BYTES=256*1024
MAX_FILES=1200
ALLOWED_SUFFIXES={'.py','.js','.jsx','.ts','.tsx','.md','.txt','.sql','.toml','.json','.yaml','.yml','.css','.html','.ini'}
IGNORED_PARTS={'.git','.hg','.svn','.venv','venv','node_modules','__pycache__','.pytest_cache','dist','build','output','outputs','.codex','.aws','.ssh','coverage'}
SECRET_NAMES={'.env','id_rsa','id_ed25519','credentials','credentials.json','secrets.json','service-account.json','.npmrc','.pypirc'}
_CREDENTIAL=re.compile(r'''(?ix)(?:api[_-]?key|secret|password|access[_-]?token)\s*[:=]\s*["'][^\s"']{12,}["']|-----BEGIN\s+(?:RSA\s+|OPENSSH\s+|EC\s+)?PRIVATE\s+KEY-----''')


def checked_path(value: str) -> str:
    value=unicodedata.normalize('NFC',value)
    if not value or len(value)>240 or '\\' in value or re.search(r'[\x00-\x1f:<>"|?*]',value):
        raise WorkspaceConflict('unsafe_archive_path')
    path=PurePosixPath(value)
    if path.is_absolute() or any(x in ('','..','.') or x.endswith(('.', ' ')) for x in value.split('/')) or len(path.parts)>14:
        raise WorkspaceConflict('unsafe_archive_path')
    if any(re.fullmatch(r'(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\..*)?',p,re.I) for p in path.parts):
        raise WorkspaceConflict('unsafe_archive_path')
    return path.as_posix()


def excluded(path, text=None):
    parts=PurePosixPath(path.casefold()).parts
    name=parts[-1]
    return (any(p in IGNORED_PARTS for p in parts) or name in SECRET_NAMES
        or name.startswith('.env') or PurePosixPath(name).suffix in {'.pem','.key','.p12','.pfx','.sqlite','.db'}
        or 'private_key' in name or 'package-lock' in name or 'yarn.lock' in name
        or bool(text is not None and _CREDENTIAL.search(text)))


def scan_zip(data: bytes, *, strip_single_root=False):
    if not data or len(data)>MAX_ARCHIVE_BYTES:raise WorkspaceConflict('archive_upload_limit')
    files={};skipped=0;seen=set()
    try:
        with ZipFile(BytesIO(data)) as archive:
            infos=archive.infolist()
            if len(infos)>MAX_FILES or sum(x.file_size for x in infos)>MAX_EXPANDED_BYTES:
                raise WorkspaceConflict('archive_expansion_limit')
            for info in infos:
                if info.flag_bits&1:raise WorkspaceConflict('encrypted_archive_not_supported')
                mode=(info.external_attr>>16)&0xFFFF
                if stat.S_ISLNK(mode) or (stat.S_IFMT(mode) and not (stat.S_ISREG(mode) or stat.S_ISDIR(mode))):
                    raise WorkspaceConflict('archive_symlink_or_special_file')
                name=info.filename.rstrip('/') if info.is_dir() else info.filename
                path=checked_path(name)
                if path.casefold() in seen:raise WorkspaceConflict('archive_duplicate_path')
                seen.add(path.casefold())
                if info.is_dir():continue
                if excluded(path) or (PurePosixPath(path).suffix.casefold() not in ALLOWED_SUFFIXES and PurePosixPath(path).name.casefold() not in {'license','copying','notice'}):
                    skipped+=1;continue
                # Never decompress excluded binary/assets. Whole-archive expanded
                # size/count limits still cover them before this loop.
                if info.file_size>MAX_FILE_BYTES or info.file_size>max(1,info.compress_size)*200:
                    raise WorkspaceConflict('archive_file_limit')
                raw=archive.read(info)
                if b'\x00' in raw:skipped+=1;continue
                try:text=raw.decode('utf-8-sig')
                except UnicodeDecodeError:
                    try:text=raw.decode('gb18030')
                    except UnicodeDecodeError:skipped+=1;continue
                if excluded(path,text):skipped+=1;continue
                # Preserve text/line identity; do not normalize newlines or Unicode.
                if text.strip():files[path]=text
    except (BadZipFile, RuntimeError, NotImplementedError) as exc:
        raise WorkspaceConflict('invalid_project_archive') from exc
    if not files:raise WorkspaceConflict('no_indexable_project_files')
    # GitHub/codeload zips have one enclosing directory, which is not a repo path.
    roots={PurePosixPath(p).parts[0] for p in files}
    removed_root=None
    if strip_single_root and len(roots)==1 and all(len(PurePosixPath(p).parts)>1 for p in files):
        removed_root=next(iter(roots))
        files={'/'.join(PurePosixPath(p).parts[1:]):text for p,text in files.items()}
    return files,{'archive_sha256':sha256(data).hexdigest(),'skipped_files':skipped,'stored_files':len(files),
                  'executed':False,'safety_version':'zip-scan-v3-2','file_hash_basis':'sha256_of_decoded_text_utf8; newlines_preserved',
                  'decoding':'utf8-sig_or_gb18030; unrecognized_and_binary_excluded','removed_root':removed_root}

"""Credential-free public GitHub downloads; fixed hosts, no shell/git execution."""
from __future__ import annotations
import ipaddress
import json
import re
import socket
import tomllib
from io import BytesIO
from zipfile import ZipFile,BadZipFile
from urllib.parse import quote,urlsplit
import httpx
from pydantic import Field
from job_agent.schemas import StrictModel
from job_agent.resume_workspace.repository import WorkspaceConflict
from job_agent.resume_workspace.project_import import MAX_ARCHIVE_BYTES,scan_zip


class GitHubImport(StrictModel):
    url: str=Field(min_length=1,max_length=300)
    ref: str=Field(default='',max_length=150)


def repository_slug(url):
    parsed=urlsplit(url)
    if parsed.scheme!='https' or parsed.netloc!='github.com' or parsed.query or parsed.fragment:
        raise WorkspaceConflict('github_public_https_url_required')
    match=re.fullmatch(r'/([A-Za-z0-9_.-]{1,80})/([A-Za-z0-9_.-]{1,100})/?',parsed.path)
    if not match:raise WorkspaceConflict('github_repository_url_required')
    owner,repo=match.groups();repo=repo.removesuffix('.git')
    if owner in ('.','..') or repo in ('','.','..'):raise WorkspaceConflict('github_repository_url_required')
    return owner,repo


def check_public_host(host):
    if host not in {'api.github.com','codeload.github.com'}:raise WorkspaceConflict('github_host_not_allowed')
    try:addresses=socket.getaddrinfo(host,443,type=socket.SOCK_STREAM)
    except OSError as exc:raise WorkspaceConflict('github_dns_unavailable') from exc
    if not addresses or any(not ipaddress.ip_address(a[4][0]).is_global for a in addresses):
        raise WorkspaceConflict('github_private_address_rejected')


class PublicGitHubImporter:
    def __init__(self,store,*,client=None,host_guard=check_public_host):
        self.store=store;self.client=client;self.host_guard=host_guard

    def _download(self,client,url,limit):
        parsed=urlsplit(url);self.host_guard(parsed.hostname)
        try:
            with client.stream('GET',url,headers={'User-Agent':'JobAgentV3-public-import','Accept':'application/vnd.github+json'}) as response:
                if response.is_redirect:raise WorkspaceConflict('github_redirect_rejected')
                if response.status_code in (403,429) and (response.headers.get('x-ratelimit-remaining')=='0' or response.status_code==429):
                    raise WorkspaceConflict('github_rate_limit_exceeded_try_zip')
                if response.status_code!=200:raise WorkspaceConflict('github_public_repository_unavailable')
                body=bytearray()
                for chunk in response.iter_bytes():
                    if len(body)+len(chunk)>limit:raise WorkspaceConflict('github_download_limit')
                    body.extend(chunk)
                return bytes(body)
        except httpx.HTTPError as exc:raise WorkspaceConflict('github_download_unavailable') from exc

    def import_project(self,owner,project_id,request:GitHubImport):
        self.store.get_project(owner,project_id)
        user,repo=repository_slug(request.url)
        if request.ref and not re.fullmatch(r'[A-Za-z0-9_.\-/]{1,150}',request.ref):raise WorkspaceConflict('github_ref_invalid')
        supplied=self.client is not None
        client=self.client or httpx.Client(timeout=httpx.Timeout(25,connect=8),trust_env=False,follow_redirects=False)
        try:
            if re.fullmatch(r'[a-fA-F0-9]{40}',request.ref):
                # A full immutable SHA needs no branch resolver. The anonymous
                # official endpoint must return its git-archive commit comment,
                # so a 40-hex branch name cannot masquerade as a different commit.
                commit=request.ref.casefold()
                raw=self._download(client,f'https://codeload.github.com/{user}/{repo}/zip/{commit}',MAX_ARCHIVE_BYTES)
                try:
                    with ZipFile(BytesIO(raw)) as archive:
                        if archive.comment.strip().decode('ascii').casefold()!=commit:raise WorkspaceConflict('github_archive_commit_mismatch')
                except (BadZipFile,UnicodeDecodeError) as exc:raise WorkspaceConflict('github_archive_commit_unverifiable') from exc
                files,safety=scan_zip(raw,strip_single_root=True)
                try:
                    declaration=tomllib.loads(files.get('pyproject.toml','')).get('project',{}).get('license','UNKNOWN')
                    license_value=declaration.get('text','UNKNOWN') if isinstance(declaration,dict) else declaration
                    if not isinstance(license_value,str) or len(license_value)>120:license_value='UNKNOWN'
                except (tomllib.TOMLDecodeError,TypeError):license_value='UNKNOWN'
                return self.store.publish_files(owner,project_id,files,origin='github',commit_sha=commit,metadata={
                    **safety,'repository_url':f'https://github.com/{user}/{repo}','license':license_value,
                    'license_basis':'upstream_pyproject_declaration_not_legal_review','source_ref':commit,
                    'public_access_basis':'anonymous_official_codeload','commit_verified_by':'git_archive_comment',
                    'private':False,'contribution_status':'self_attested_not_verified'})
            try:
                meta=json.loads(self._download(client,f'https://api.github.com/repos/{user}/{repo}',100000))
                if meta.get('private') is not False:raise WorkspaceConflict('private_repository_not_authorized')
                ref=request.ref or meta['default_branch']
                result=json.loads(self._download(client,f'https://api.github.com/repos/{user}/{repo}/commits/{quote(ref,safe="")}',200000))
                commit=result['sha']
                if not re.fullmatch(r'[a-f0-9]{40}',commit):raise WorkspaceConflict('github_commit_invalid')
            except WorkspaceConflict:raise
            except (ValueError,KeyError,TypeError) as exc:raise WorkspaceConflict('github_metadata_invalid') from exc
            raw=self._download(client,f'https://codeload.github.com/{user}/{repo}/zip/{commit}',MAX_ARCHIVE_BYTES)
            files,safety=scan_zip(raw,strip_single_root=True)
            return self.store.publish_files(owner,project_id,files,origin='github',commit_sha=commit,metadata={
                **safety,'repository_url':f'https://github.com/{user}/{repo}','license':(meta.get('license') or {}).get('spdx_id','UNKNOWN'),
                'source_ref':str(ref)[:150],'private':False,'contribution_status':'self_attested_not_verified'})
        finally:
            if not supplied:client.close()

"""Product adapter to the existing evidence kernel, with an explicit local precheck.

No vector score or keyword hit is promoted to verified semantic support. Only
existing entry order may be changed; this module does not generate resume claims.
"""
