    AtomEvidenceResult, EvidenceBundle, EvidenceLink, EvidenceMappingV2,
    EvidenceRunManifest, ParentRequirement, RequirementAnalysis, RequirementAtom,
    SourceCatalog, SourceDocumentRef,
)
