def extract_upload(filename: str, data: bytes):
    """No client-controlled paths, archive extraction or external OCR calls."""
    suffix = Path(filename.replace("\\", "/")).suffix.lower()
    if suffix not in {".txt", ".md", ".pdf", ".docx"}:
        raise ImportErrorCode("unsupported_file_type")
    if not data:
        raise ImportErrorCode("empty_upload")
    if len(data) > MAX_UPLOAD_BYTES:
        raise ImportErrorCode("upload_too_large")
    if suffix == ".pdf":
        if not data.startswith(b"%PDF-"):
            raise ImportErrorCode("invalid_pdf")
        try:
            from pypdf import PdfReader
            reader = PdfReader(io.BytesIO(data))
            if reader.is_encrypted:
                raise ImportErrorCode("encrypted_pdf")
            if len(reader.pages) > 40:
                raise ImportErrorCode("too_many_pages")
        except ImportErrorCode:
            raise
        except Exception as exc:
            raise ImportErrorCode("invalid_pdf") from exc
    if suffix == ".docx":
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as archive:
                files = archive.infolist()
                if len(files) > 2000 or sum(item.file_size for item in files) > 30 * 1024 * 1024:
                    raise ImportErrorCode("expanded_document_too_large")
                if "word/document.xml" not in archive.namelist():
                    raise ImportErrorCode("invalid_docx")
                if any(item.flag_bits & 1 for item in files):
                    raise ImportErrorCode("encrypted_docx")
        except (zipfile.BadZipFile, RuntimeError) as exc:
            raise ImportErrorCode("invalid_docx") from exc
    with TemporaryDirectory(prefix="resume-import-") as directory:
        path = Path(directory) / ("upload" + suffix)
        path.write_bytes(data)
        try:
            result = load_source(path)
        except ValueError as exc:
            code = "needs_ocr" if suffix == ".pdf" and "no extractable text" in str(exc).lower() else "document_extraction_failed"
            raise ImportErrorCode(code) from exc
    if len(result.text) > 100_000:
        raise ImportErrorCode("extracted_text_too_large")
    return result

def checked_path(value: str) -> str:
    value=unicodedata.normalize('NFC',value)
    if not value or len(value)>240 or '\\' in value or re.search(r'[\x00-\x1f:<>"|?*]',value):
        raise WorkspaceConflict('unsafe_archive_path')
    path=PurePosixPath(value)
    if path.is_absolute() or any(x in ('','..','.') or x.endswith(('.', ' ')) for x in value.split('/')) or len(path.parts)>14:
        raise WorkspaceConflict('unsafe_archive_path')
    if any(re.fullmatch(r'(?:con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\..*)?',p,re.I) for p in path.parts):
        raise WorkspaceConflict('unsafe_archive_path')
    return path.as_posix()

def scan_zip(data: bytes, *, strip_single_root=False):
    if not data or len(data)>MAX_ARCHIVE_BYTES:raise WorkspaceConflict('archive_upload_limit')
    files={};skipped=0;seen=set()
    try:
        with ZipFile(BytesIO(data)) as archive:
            infos=archive.infolist()
            if len(infos)>MAX_FILES or sum(x.file_size for x in infos)>MAX_EXPANDED_BYTES:
                raise WorkspaceConflict('archive_expansion_limit')
            for info in infos:
                if info.flag_bits&1:raise WorkspaceConflict('encrypted_archive_not_supported')
                mode=(info.external_attr>>16)&0xFFFF
                if stat.S_ISLNK(mode) or (stat.S_IFMT(mode) and not (stat.S_ISREG(mode) or stat.S_ISDIR(mode))):
                    raise WorkspaceConflict('archive_symlink_or_special_file')
                name=info.filename.rstrip('/') if info.is_dir() else info.filename
                path=checked_path(name)
                if path.casefold() in seen:raise WorkspaceConflict('archive_duplicate_path')
                seen.add(path.casefold())
                if info.is_dir():continue
                if excluded(path) or (PurePosixPath(path).suffix.casefold() not in ALLOWED_SUFFIXES and PurePosixPath(path).name.casefold() not in {'license','copying','notice'}):
                    skipped+=1;continue
                # Never decompress excluded binary/assets. Whole-archive expanded
                # size/count limits still cover them before this loop.
                if info.file_size>MAX_FILE_BYTES or info.file_size>max(1,info.compress_size)*200:
                    raise WorkspaceConflict('archive_file_limit')
                raw=archive.read(info)
                if b'\x00' in raw:skipped+=1;continue
                try:text=raw.decode('utf-8-sig')
                except UnicodeDecodeError:
                    try:text=raw.decode('gb18030')
                    except UnicodeDecodeError:skipped+=1;continue
                if excluded(path,text):skipped+=1;continue
                # Preserve text/line identity; do not normalize newlines or Unicode.
                if text.strip():files[path]=text
    except (BadZipFile, RuntimeError, NotImplementedError) as exc:
        raise WorkspaceConflict('invalid_project_archive') from exc
    if not files:raise WorkspaceConflict('no_indexable_project_files')
    # GitHub/codeload zips have one enclosing directory, which is not a repo path.
    roots={PurePosixPath(p).parts[0] for p in files}
    removed_root=None
    if strip_single_root and len(roots)==1 and all(len(PurePosixPath(p).parts)>1 for p in files):
        removed_root=next(iter(roots))
        files={'/'.join(PurePosixPath(p).parts[1:]):text for p,text in files.items()}
    return files,{'archive_sha256':sha256(data).hexdigest(),'skipped_files':skipped,'stored_files':len(files),
                  'executed':False,'safety_version':'zip-scan-v3-2','file_hash_basis':'sha256_of_decoded_text_utf8; newlines_preserved',
                  'decoding':'utf8-sig_or_gb18030; unrecognized_and_binary_excluded','removed_root':removed_root}

def repository_slug(url):
    parsed=urlsplit(url)
    if parsed.scheme!='https' or parsed.netloc!='github.com' or parsed.query or parsed.fragment:
        raise WorkspaceConflict('github_public_https_url_required')
    match=re.fullmatch(r'/([A-Za-z0-9_.-]{1,80})/([A-Za-z0-9_.-]{1,100})/?',parsed.path)
    if not match:raise WorkspaceConflict('github_repository_url_required')
    owner,repo=match.groups();repo=repo.removesuffix('.git')
    if owner in ('.','..') or repo in ('','.','..'):raise WorkspaceConflict('github_repository_url_required')
    return owner,repo

def check_public_host(host):
    if host not in {'api.github.com','codeload.github.com'}:raise WorkspaceConflict('github_host_not_allowed')
    try:addresses=socket.getaddrinfo(host,443,type=socket.SOCK_STREAM)
    except OSError as exc:raise WorkspaceConflict('github_dns_unavailable') from exc
    if not addresses or any(not ipaddress.ip_address(a[4][0]).is_global for a in addresses):
        raise WorkspaceConflict('github_private_address_rejected')

def _load(self, db, owner, match_id):
    row = self._row(db,owner,match_id)
    if row['status'] != 'complete':raise WorkspaceConflict('match_not_complete')
    if digest(row['payload_json'])!=row['payload_hash']:
        raise InvalidProvenance('match_integrity_failed')
    payload = MatchPayload.model_validate_json(row['payload_json'])
    version = self.workspace._version(db,row['resume_id'],row['version_id'])
    self.workspace._validate_document(db,owner,version.document)
    self._validate_payload(row,payload,version)
    return row, payload, version

def read(self, catalog: SourceCatalog, source_id: str) -> str:
    ref = self._document(catalog, source_id)
    text = self.texts.get(source_id)
    if text is None or digest(text) != ref.content_hash:
        raise MatchError('match_source_integrity_failed')
    return text

def materialize(source: SourceRecord, candidate: ParseCandidate) -> DraftDocument:
    payload: dict = {"personal": {}}
    paths = set()
    for item in candidate.fields:
        checked_path(item.path)
        if item.path in paths:
            raise ParseError("duplicate_field_path")
        paths.add(item.path)
        quote = item.exact_quote
        start = item.start
        if start is None or item.end != start + len(quote) or source.text[start:item.end] != quote:
            start = source.text.find(quote)
            if start < 0:
                raise ParseError("quote_not_found")
            if source.text.find(quote, start + 1) >= 0:
                raise ParseError("ambiguous_quote")
        fact = ResumeFact(
            fact_id="f-" + hashlib.sha256(f"{source.source_id}:{item.path}".encode()).hexdigest()[:20],
            text=quote, source=SourceSpan(source_id=source.source_id, content_hash=source.content_hash,
                                         start=start, end=start + len(quote)),
        )
        set_field(payload, item.path, fact.model_dump(mode="json"))
    # Reject sparse parser indexes rather than silently changing their meaning.
    def sparse(value):
        if isinstance(value, list):
            if any(item is None for item in value):
                raise ParseError("sparse_field_indexes")
            for item in value:
                sparse(item)
        elif isinstance(value, dict):
            for item in value.values():
                sparse(item)
    sparse(payload)
    return DraftDocument.model_validate(compact(payload))

def validate_bundle(store: VersionSourceStore, bundle: EvidenceBundle):
    if bundle.sources != store.catalog:
        raise MatchError('match_source_integrity_failed')
    if bundle.manifest.source_fingerprint != digest(''.join(d.content_hash for d in store.catalog.documents)):
        raise MatchError('match_source_integrity_failed')
    for parent in bundle.requirements.parents:
        if parent.source_span.source_id != 'jd':raise MatchError('invalid_jd_span')
        store.validate_span(store.catalog,parent.source_span)
    for atom in bundle.requirements.atoms:
        if atom.source_span.source_id != 'jd':raise MatchError('invalid_jd_span')
        store.validate_span(store.catalog,atom.source_span)
    if {a.atom_id for a in bundle.requirements.atoms}!={r.atom_id for r in bundle.mapping.atom_results}:
        raise MatchError('invalid_mapping_coverage')
    for result in bundle.mapping.atom_results:
        for link in result.links:
            if link.source_span.source_id not in store.origins or link.level.value!='C1' or not link.needs_confirmation:
                raise MatchError('match_evidence_boundary_violation')
            store.validate_span(store.catalog,link.source_span)
        if result.match_status != EvidenceMappingService._match_status(result.links):
            raise MatchError('invalid_match_status')
        if result.has_contradiction != any(l.support_status=='contradictory' for l in result.links):
            raise MatchError('invalid_conflict_flag')
    if EvidenceProjectionService().for_resume(bundle).claims:
        raise MatchError('match_evidence_boundary_violation')

def extract_upload(filename: str, data: bytes):
    """No client-controlled paths, archive extraction or external OCR calls."""
    suffix = Path(filename.replace("\\", "/")).suffix.lower()
    if suffix not in {".txt", ".md", ".pdf", ".docx"}:
        raise ImportErrorCode("unsupported_file_type")
    if not data:
        raise ImportErrorCode("empty_upload")
    if len(data) > MAX_UPLOAD_BYTES:
        raise ImportErrorCode("upload_too_large")
    if suffix == ".pdf":
        if not data.startswith(b"%PDF-"):
            raise ImportErrorCode("invalid_pdf")
        try:
            from pypdf import PdfReader
            reader = PdfReader(io.BytesIO(data))
            if reader.is_encrypted:
                raise ImportErrorCode("encrypted_pdf")
            if len(reader.pages) > 40:
                raise ImportErrorCode("too_many_pages")
        except ImportErrorCode:
            raise
        except Exception as exc:
            raise ImportErrorCode("invalid_pdf") from exc
    if suffix == ".docx":
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as archive:
                files = archive.infolist()
                if len(files) > 2000 or sum(item.file_size for item in files) > 30 * 1024 * 1024:
                    raise ImportErrorCode("expanded_document_too_large")
                if "word/document.xml" not in archive.namelist():
                    raise ImportErrorCode("invalid_docx")
                if any(item.flag_bits & 1 for item in files):
                    raise ImportErrorCode("encrypted_docx")
        except (zipfile.BadZipFile, RuntimeError) as exc:
            raise ImportErrorCode("invalid_docx") from exc
    with TemporaryDirectory(prefix="resume-import-") as directory:
        path = Path(directory) / ("upload" + suffix)
        path.write_bytes(data)
        try:
            result = load_source(path)
        except ValueError as exc:
            code = "needs_ocr" if suffix == ".pdf" and "no extractable text" in str(exc).lower() else "document_extraction_failed"
            raise ImportErrorCode(code) from exc
    if len(result.text) > 100_000:
        raise ImportErrorCode("extracted_text_too_large")
    return result

